            Describe.Lean(DescribeId.Create("actualsource-second-peak-a2-joint-lift"), DeclarationHandle.Create("D5/S3/Combinatorics/Circle/FourNegative/SecondPeakA2/Endpoint.actualSource_second_peak_a2_joint_lift"), H("actualSource_second_peak_a2_joint_lift"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("theorem actualSource_second_peak_a2_joint_lift (b c d : \u2115)     (hc : 3\u2264c) (hd : c+2\u2264d) (hb : b=d+1 \u2228 b=d+2) :     \u2203 sigma : List (Fin (2+b+c+d)), \u2203 j : \u2115, j\u22642+b+c+d \u2227       OriginalOrder (2+b+c+d) (1+2^2+2^(2+b)+2^(2+b+c)) sigma \u2227       OriginalOrder (2+b+c+d+1) (2*(1+2^2+2^(2+b)+2^(2+b+c)))         (earWord (2+b+c+d) sigma j) \u2227       (\u2200 r n : \u2115, ((((List.replicate r sigma).flatten).take n).map         (actualSource (2+b+c+d) (1+2^2+2^(2+b)+2^(2+b+c)))).sum \u2208         Set.Icc (0:\u2124) (modulus (2+b+c+d)/2)) \u2227       (\u2200 r n : \u2115, ((((List.replicate r (earWord (2+b+c+d) sigma j)).flatten).take n).map         (actualSource (2+b+c+d+1) (2*(1+2^2+2^(2+b)+2^(2+b+c))))).sum \u2208         Set.Icc (0:\u2124) (modulus (2+b+c+d))) \u2227       (\u2200 r : \u2115,         (((List.replicate r sigma).flatten).map           (actualSource (2+b+c+d) (1+2^2+2^(2+b)+2^(2+b+c)))).sum=0 \u2227         (((List.replicate r (earWord (2+b+c+d) sigma j)).flatten).map           (actualSource (2+b+c+d+1) (2*(1+2^2+2^(2+b)+2^(2+b+c))))).sum=0)"))), DescribeRole.Theorem)), []));
